-- Generated by data_pipeline/zetaris_sql/generate.py. Do not edit by hand:
-- change the generator or data_pipeline/suppliers.yaml, then regenerate.

-- App-facing views in container risk. The app reads only these, with a role key:
-- buyer views never carry unit prices, order values, contract values or notes.
-- Row scope (the buyer's category) is a bound parameter in the tool layer.

CREATE SCHEMASTORE CONTAINER risk;

-- Suppliers with contract value and end date (risk managers only).
CREATE OR REPLACE SCHEMASTORE VIEW v_suppliers_full WITH CONTAINER risk AS
SELECT
    s.supplier_id,
    s.name,
    s.cik,
    s.country_iso,
    s.category,
    s.site_lat,
    s.site_lon,
    c.annual_value_eur,
    c.end_date AS contract_end_date
FROM erp_pg.suppliers s
LEFT JOIN erp_pg.contracts c ON c.supplier_id = s.supplier_id;

-- Suppliers for buyers: contract end date, no contract value.
CREATE OR REPLACE SCHEMASTORE VIEW v_suppliers_buyer WITH CONTAINER risk AS
SELECT
    s.supplier_id,
    s.name,
    s.cik,
    s.country_iso,
    s.category,
    s.site_lat,
    s.site_lon,
    c.end_date AS contract_end_date
FROM erp_pg.suppliers s
LEFT JOIN erp_pg.contracts c ON c.supplier_id = s.supplier_id;

-- Open purchase orders with unit price and order value (risk managers only).
CREATE OR REPLACE SCHEMASTORE VIEW v_open_orders_full WITH CONTAINER risk AS
SELECT
    po.po_id,
    po.supplier_id,
    po.part_id,
    p.description AS part_description,
    p.criticality,
    po.category,
    po.qty,
    po.unit_price_eur,
    CAST(po.qty * po.unit_price_eur AS DECIMAL(16, 2)) AS order_value_eur,
    po.due_date
FROM erp_pg.purchase_orders po
JOIN erp_pg.parts p ON p.part_id = po.part_id
WHERE po.status = 'open';

-- Open purchase orders for buyers: no unit price and no order value (derived).
CREATE OR REPLACE SCHEMASTORE VIEW v_open_orders_buyer WITH CONTAINER risk AS
SELECT
    po.po_id,
    po.supplier_id,
    po.part_id,
    p.description AS part_description,
    p.criticality,
    po.category,
    po.qty,
    po.due_date
FROM erp_pg.purchase_orders po
JOIN erp_pg.parts p ON p.part_id = po.part_id
WHERE po.status = 'open';

-- Who supplies which part, with part criticality and single-source flag.
CREATE OR REPLACE SCHEMASTORE VIEW v_part_sourcing WITH CONTAINER risk AS
SELECT
    ps.part_id,
    ps.supplier_id,
    p.description AS part_description,
    p.category,
    p.criticality,
    ps.share_pct,
    ps.is_single_source
FROM erp_pg.part_sourcing ps
JOIN erp_pg.parts p ON p.part_id = ps.part_id;

-- Deliveries per purchase order; days_late is NULL while the order is open.
CREATE OR REPLACE SCHEMASTORE VIEW v_deliveries WITH CONTAINER risk AS
SELECT
    d.po_id,
    po.supplier_id,
    po.part_id,
    po.category,
    po.status,
    d.promised_date,
    d.delivered_date,
    datediff(d.delivered_date, d.promised_date) AS days_late
FROM erp_pg.deliveries d
JOIN erp_pg.purchase_orders po ON po.po_id = d.po_id;

-- Contracts with buyer_notes (free text, untrusted; risk managers only).
CREATE OR REPLACE SCHEMASTORE VIEW v_contracts_full WITH CONTAINER risk AS
SELECT
    supplier_id,
    annual_value_eur,
    end_date,
    buyer_notes
FROM erp_pg.contracts;

-- EDGAR revenue facts per public supplier (supplier_id and CIK from suppliers.yaml).
-- Raw fact history: a filing repeats earlier periods and 10-Ks hold quarterly facts,
-- so callers pick periods by period_start/period_end, not by fiscal_year alone.
CREATE OR REPLACE SCHEMASTORE VIEW v_supplier_revenue WITH CONTAINER risk AS
SELECT 'S0001' AS supplier_id, '0000097476' AS cik, fiscal_year, fiscal_period, period_start, period_end, form_type, value_usd
FROM sr_edgar.s0001_revenue
UNION ALL
