FROM sr_edgar.s0004_revenue
UNION ALL
SELECT 'S0005' AS supplier_id, '0001306830' AS cik, fiscal_year, fiscal_period, period_start, period_end, form_type, value_usd
FROM sr_edgar.s0005_revenue
UNION ALL
SELECT 'S0006' AS supplier_id, '0001675149' AS cik, fiscal_year, fiscal_period, period_start, period_end, form_type, value_usd
